import{_ as r,a as o}from"./chunks/8ee1377e9a95e9fe5181.DzpIsciU.js";import{_ as n}from"./chunks/97922e77c3d19f61f9de.CPLfpGYK.js";import{_ as p,C as i,o as s,c as l,j as a,a as d,E as c,a5 as h}from"./chunks/framework.DNkHA0lr.js";const P=JSON.parse('{"title":"如何避免最终沦为平庸","description":"","frontmatter":{"title":"如何避免最终沦为平庸","originalTitle":"How To Not End Up Mediocre","date":"2022-03-08","originalUrl":"https://thedankoe.com/letters/how-to-not-end-up-mediocre/","minutes":8,"sourceHash":"63d91a15158e71daa1acc85e69a341151910348bf58c685773c691a169fb044c","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-to-not-end-up-mediocre/"}]]},"headers":[],"relativePath":"letters/how-to-not-end-up-mediocre.md","filePath":"letters/how-to-not-end-up-mediocre.md"}'),m={name:"letters/how-to-not-end-up-mediocre.md"};function f(u,e,_,g,b,k){const t=i("ArticleMeta");return s(),l("div",null,[e[0]||(e[0]=a("h1",{id:"如何避免最终沦为平庸",tabindex:"-1"},[d("如何避免最终沦为平庸 "),a("a",{class:"header-anchor",href:"#如何避免最终沦为平庸","aria-label":'Permalink to "如何避免最终沦为平庸"'},"​")],-1)),c(t),e[1]||(e[1]=h('<p>我一生都致力于剖析究竟是什么让成功人士取得了成功。正因为如此，我花了很多时间去观察那些平庸的人，因为在明白该做什么之前，必须先明白不该做什么。</p><p>经过多年的学习、观察和以拼凑出完整拼图为目的的创作——我有一个观点要与你分享。这个观点是基于我在灵性、哲学、商业、健康、表现力、心态等许多领域的研究所形成的。尽管我非常希望这能成为一种放之四海而皆准的方法，但事实可能并非如此。然而，我确实认为成功是直觉性的。问题在于，人们被现代生活的干扰淹没了他们的直觉。</p><p>这个观点会有缺陷。我鼓励你去质疑它、研究它，并形成你自己的看法。我写作的意义在于理解。在于留下一个参考点。在于点亮我用所有内容绘制的这张地图上的更多区域。这张地图会有漏洞，但在我未来继续写这封信的岁月里，这些漏洞会被慢慢修补。</p><p>这个观点构成了我“现代精通（Modern Mastery）”使命的基础。去挖掘你的直觉，依凭它去生活，并利用你手头的现代工具——而不是让它们毁了你的生活。我们开始吧。</p><h2 id="顺应自然而活" tabindex="-1">顺应自然而活 <a class="header-anchor" href="#顺应自然而活" aria-label="Permalink to &quot;顺应自然而活&quot;">​</a></h2><p>在我之前关于<a href="https://www.modernmastery.co/post/an-argument-for-mental-minimalism-stop-thinking-start-doing" target="_blank" rel="noreferrer">精神极简主义</a>和<a href="https://www.modernmastery.co/post/the-brainwashing-system-i-use-on-myself-to-be-happy" target="_blank" rel="noreferrer">认知</a>的几封信中，我曾经讨论过这个话题。顺应“事物的本来面目”并依循自然生活。前几天散步时，我在听马可·奥勒留（Marcus Aurelius）的《沉思录》，注意到他经常说我们必须“顺应自然而活”。对以前的我来说，这话根本说不通。现在，我有更多的思想弹药来为你把这事讲明白了。</p><p>对于那些不熟悉整体论（holism）或全子理论（holonic theory）的人，我给你们做个简要的介绍。“全子（holon）”——由肯·威尔伯（Ken Wilber）创造的一个术语——是现实的基石。它既是一个整体，也是一个部分。原子是一个整体，但它也是分子的一部分。分子是一个整体，但它也是细胞的一部分。这些全子在所有现实层面上向无限方向延伸。一直向上，一直向下。与其他全子形成紧密的连接。你是一个全子。宇宙是一个全子。一栋建筑是一个全子。一粒沙子也是一个全子。万事万物皆是全子。在我们深入之前，我鼓励你停下来，对此感到敬畏。这到底能向下延伸多深？又能向上延伸多高？</p><p>如下图所示，这在宏观层面上得到了体现，并且在各大宗教和哲学中都能注意到这种模式。如果你想更深入地了解这一切，我推荐你从肯·威尔伯的《万物简史》（A Brief Explanation Of Everything）这本书开始。</p><p><img src="'+r+'" alt=""></p><p>存在之链 (The Great Chain Of Being)</p><p>“全子”有与之相关的12条原则。这些原则反映了它们的进化行为。现在，你只需明白我们已经从自然、身体、心智进化到了精神。植物、动物，以及现在正在经历灵性体验的人类。全子在出现和进化的同时，也带着之前的一切一起前行。在我们的根源处——我们的存在——我们就是自然。然而我们带有动物性的驱动力和特征。而现在我们处于心智（mind）阶段。与自负（ego）作斗争，理解它，将其置于我们的控制之下，同时触及精神“领域”。</p><p>我知道这要么让你感到无聊，要么激发了你探索更多的兴趣，所以我将继续往下讲，让那些未知事物的探索者去做他们该做的事。在此之前，请明白自然是我们的根基。自然不是平庸的、坏的或邪恶的。当这些都是由心智创造出来的观念时，自然怎么可能是那些东西呢？</p><h2 id="孩童般的惊奇感" tabindex="-1">孩童般的惊奇感 <a class="header-anchor" href="#孩童般的惊奇感" aria-label="Permalink to &quot;孩童般的惊奇感&quot;">​</a></h2><p>作为一个孩子，你是最接近自然的。你自信、好奇、富有创造力、充满爱心、爱玩且真实。你的行为基于你的直觉和孩童般的冲动。当文化规训开始发挥作用，你的心智开始发育时，你开始形成你的信念、偏见、意见等。你开始掩盖你曾经拥有的那种孩童般的惊奇感。你的心智开始接管一切，你开始靠被条件反射规训出的冲动生活，而不是与自然共生。</p><p>这个论点的核心是说，你的生物学本能（自然属性）就是去爱、去创造、去玩耍，并用你真实的自信刺透这个世界。特别是如果你想达到新的高度并“涌现”至下一个发展阶段（稍后会详细讲）。</p><p>“但是 Dan，如果我们只凭直觉行事，我们最后可能会做蠢事。”</p><p>是啊，这其实正是我的重点。如果做点蠢事是你注定该走的方向，那它为什么会让你害怕呢？除此以外，这也是我们进化到心智阶段的原因。它是一种生存机制。一种工具。你可以通过愿景、目标和优先级来框定你的注意力，从而做出有意识和积极的决定。当我们剥去文化规训带来的负面影响，并更加贴近自然时——我们的直觉就会变得更加准确。好奇心成为了我们的向导。自我教育和自力更生开始胜过依赖他人。我们过上了原本该过的生活。</p><p>我想提一下肯·威尔伯的“前/超模型”与“前/超谬误（pre-trans fallacy）”。它提醒了我，为什么我相信学习形而上学、哲学和灵性，要比读没完没了的书更好（尽管那些书对于赚钱这种短期策略是很好的）。</p><p>你见过智商钟形曲线的梗图（meme）吗？那是仿照肯的“前/超谬误”制作的，反映在生活的各个发展领域中。这个梗图之所以总让你觉得“靠，太真实了”，是有原因的。</p><p><img src="'+o+'" alt=""></p><p>智商钟形曲线梗图</p><p>你必须在生活的许多领域——以及整个人生中——经历各个发展阶段（前理性、理性和超理性）。就你的技能组合而言，你必须经历这些发展阶段，直到那项技能升华为艺术。精英运动员通常将他们的巅峰表现视为一种精神境界。这意味着他们已经将自己和技能磨练到了超越思维需求的程度。</p><p>而这就是关键所在。你<strong>必须</strong>让自己看起来像个傻瓜。你<strong>必须</strong>犯错，让自己下不来台。在你到达“可持续发展的斜坡（slope of sustainability）”之前，你必须爬上“愚昧之巅（peak of mount stupid）”并跌入“绝望之谷（valley of despair）”。正如 Joey Justice 曾经说过的那样：“一个人在变得纯粹通透（based）之前，必先经历一段令人尴尬（cringe）的时期。” 只是为了再次令人尴尬。一种开悟版的尴尬。</p><p><img src="'+n+'" alt=""></p><p>达克效应 (Dunning-Kruger Effect)</p><p>许多古代导师、灵性大师和现代思想领袖对于你宏观的人生目标得出了相似的结论。那就是“提升人类集体意识”、“传承你的经验”，以及其他变体。我们该怎么做呢？通过接触自然，倾听自然，让自然的所有积极品质引导我们走向自己的自然本性，并据此进行创造。</p><p>当你剥除心智的固有认知，赋予其秩序，并保持好奇开放的心态时，你就让命运发挥了它的作用。你意识到了阻碍你前进的现代干扰，并让好奇心主导一切。你据此去学习、去运用、去体验。提升你的觉知、理解力和意识。这其中美妙的一点在于，“创造-者经济（Create-or economy）”正在蓬勃发展。现代线上商业已经成为一个人们能够分享其独特且多样的（积极而自然的）经验的地方，以在规模上“提升人类集体意识”。通过充满爱心、真实且富有创造力的努力来影响世界，帮助他人在生活的各个领域获得发展。</p><h2 id="焦点框定" tabindex="-1">焦点框定 <a class="header-anchor" href="#焦点框定" aria-label="Permalink to &quot;焦点框定&quot;">​</a></h2><p>心智渴望理解。它通过秩序来理清事物。绘制地图、讲述故事、概念、标签、符号以及其余种种。你的现实不过就是这些东西。一层又一层的故事和概念，建立在你观察世界的感知滤镜之上——这种滤镜通常是由文化和程式化规训塑造而成的。</p><p>这不是件坏事。这是你需要有所觉知的事。心智喜欢秩序，那为什么不以一种使“存在（being）”与“成为（becoming）”相一致的方式来给它排布秩序呢？自然与成长。有些人称之为心态（mindset），但我喜欢将其视为“焦点框定（focus framing）”。考虑到我们的注意力正在被现代干扰所操纵和偷走，我们必须通过保持专注，将我们的注意力引向积极、自然的方向。</p><p>同样，这就是为什么《创造力层级体系（The Creation Hierarchy）》以及/或者持续使用和迭代《能量计划表（The Power Planner）》如此重要。无论你是否知道自己的愿景、惯例、目标、优先事项及其他种种是否“好”——仅仅是把它们写下来，就会开始训练你的心智朝它们靠拢。你会变得对更好的生活更有意识。你可以开始迭代你的愿景，因为这些东西起到了参考点的作用。你的好奇心将开始展现，因为你会注意到那些可能与你的愿景、目标、项目等相契合的事物。然后，突然之间，就像来自神灵的使者一样，你会感觉到一种“引力”，驱使你全心全意投入到<strong>你</strong>真正想做的事情上。而不是那些你被程式化规训后以为自己想做的事。</p><p>如果你不想落入平庸，你需要理顺你的心智——框定你的焦点——朝向一个卓越的未来。你需要写下你当前想要什么。不带评判地观察你不想要什么。随着时间的推移，让你的愿景变得越来越清晰。</p><p>你必须清空头脑中的一切，除了对当下的观察、执行和存在（80%），再配以激发你热情的对愿景、目标和优先事项的微妙提醒（20%）。这场战斗创造了张力。张力创造了故事。故事创造了意义。</p><h2 id="停止在乎" tabindex="-1">停止在乎 <a class="header-anchor" href="#停止在乎" aria-label="Permalink to &quot;停止在乎&quot;">​</a></h2><p>最近，我越来越多地试着对任何事都“不在乎”。这需要大量的练习和成长。我已经“停止在乎”健康，取而代之的是做出与我想成为的人相符的、有意识的决定。当决定早已做好，我根本不需要在深思熟虑上浪费精力。我已经“停止在乎”商业，而是完全根据自己的兴趣来构建项目。如果我没有经历过过度思考的“理性”阶段，我就不会具备深度、细节把控力以及必要的信息，来毫不费力地让这些项目运转起来。</p><p>现在的我已经把生活变成：带着清醒的意识，做着我确切“想做”的事，只为揭开我真正想要的那条路——然后一遍又一遍地重复这个循环。这种张力创造了意义，同时，在我选择发展自我的领域中，朝着无限积极的方向前进。</p><p>说了这么多，我其实还在摸索中。从我所有的学习中得出的核心一课就是，你只需带着清醒的意识，去做你想做的事。</p><p>这封信就写到这里。如果你想全面提升你的心智、身体、精神和业务 —— <a href="https://join.modernmastery.co/" target="_blank" rel="noreferrer">点击这里加入 Modern Mastery HQ，获取经过验证的框架、系统、循序渐进的路线图以及个性化的帮助。</a></p><hr><p><a href="/en/letters/how-to-not-end-up-mediocre">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',40))])}const x=p(m,[["render",f]]);export{P as __pageData,x as default};
